  { name: 'Carla Ibanez', email: 'carla.i@example.com', phone: '+15555550103', state: 'FL', crop: 'Citrus', acreage: 22, irrigation_type: 'micro-sprinkler', organic: false, notes: 'Asking about the YieldMAX Program specifically.' },
  { name: 'Tom Whitfield', email: 'tom.w@example.com', phone: '+15555550104', state: 'NE', crop: 'Corn', acreage: 380, irrigation_type: 'pivot', organic: false, notes: 'Runs 2 center pivots, wants a quote for both.' },
  { name: 'Renee Dupont', email: 'renee.d@example.com', phone: '+15555550105', state: 'ID', crop: 'Potatoes', acreage: 45, irrigation_type: 'pivot', organic: false, notes: '' }
];
return leads.map(l => ({ json: l }));

// Deterministic pricing-tier lookup against Harvest Harmonics' real published rate card
// (harvestharmonics.com/crop-booster):
//   - Pivot irrigation: $10,000 (<=150 acres) or $20,000 (<=400 acres)
//   - Up to 5 acres: $1,000 flat for 2 years
//   - 6-9 acres: $250/acre/year
//   - 10-29 acres: eligible for YieldMAX Program (needs a consult, not a flat quote)
//   - 30+ acres: eligible for further volume discounts (needs a consult)
// No AI needed here — this is a pure lookup table a human sales rep uses today by hand.

return items.map(item => {
  const lead = item.json;
  const acres = Number(lead.acreage) || 0;
  const isPivot = lead.irrigation_type === 'pivot';

  let tier, quote_summary, requires_consult;

  if (isPivot) {
    if (acres <= 150) {
      tier = 'pivot_small';
      quote_summary = 'Pivot program: $10,000 for up to 150 acres under this pivot.';
      requires_consult = false;
    } else if (acres <= 400) {
      tier = 'pivot_large';
      quote_summary = 'Pivot program: $20,000 for up to 400 acres under this pivot.';
      requires_consult = false;
    } else {
      tier = 'pivot_oversized';
      quote_summary = 'Pivot acreage exceeds 400 — needs a custom multi-zone quote.';
      requires_consult = true;
    }
  } else if (acres <= 5) {
    tier = 'starter';
    quote_summary = 'Starter rate: $1,000 flat for 2 years (up to 5 acres).';
    requires_consult = false;
  } else if (acres <= 9) {
    tier = 'small_grower';
    quote_summary = `Small grower rate: $250/acre/year \u00d7 ${acres} acres = $${acres * 250}/year.`;
    requires_consult = false;
  } else if (acres <= 29) {
    tier = 'yieldmax_eligible';
    quote_summary = 'Eligible for the YieldMAX 2-year value-added program — schedule a consult for exact rate.';
    requires_consult = true;
  } else {
    tier = 'volume_discount';
    quote_summary = '30+ acres — eligible for further discounts/benefits, schedule a consult.';
    requires_consult = true;
  }

  lead.pricing_tier = tier;
  lead.quote_summary = quote_summary;
  lead.requires_consult = requires_consult;
  return { json: lead };
});
